using System.Management;using System.Security.Cryptography;using System.Text;using Microsoft.Win32;
namespace YoungOne.MediaControl.Agent.Identity;
public sealed class DeviceEvidenceProvider{public DeviceEvidence Collect(){var parts=new SortedDictionary<string,string>(StringComparer.Ordinal){["smbios"]=Query("Win32_ComputerSystemProduct","UUID"),["bios"]=Query("Win32_BIOS","SerialNumber"),["board"]=Query("Win32_BaseBoard","SerialNumber"),["machineGuid"]=ReadMachineGuid()};string canonical=string.Join("|",parts.Select(x=>$"{x.Key}={Normalize(x.Value)}"));return new DeviceEvidence(Sha256(canonical),parts.ToDictionary(x=>x.Key,x=>Sha256(Normalize(x.Value))),Environment.MachineName);}
 private static string Query(string type,string property){using var searcher=new ManagementObjectSearcher($"SELECT {property} FROM {type}");foreach(ManagementObject item in searcher.Get())return item[property]?.ToString()??"";return "";}private static string ReadMachineGuid(){using RegistryKey? key=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Cryptography");return key?.GetValue("MachineGuid")?.ToString()??"";}private static string Normalize(string value)=>new(value.Where(char.IsLetterOrDigit).Select(char.ToUpperInvariant).ToArray());private static string Sha256(string value)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();}
public sealed record DeviceEvidence(string AggregateHash,IReadOnlyDictionary<string,string>ComponentHashes,string Hostname);
